'use strict';

const appScope=require('../../shared/services/appScope');
const contract=require('../../contracts/scheduler');
const crypto=require('crypto');

function boot(ctx){ctx.log.info('scheduler booting',{module:'scheduler'});}
function teardown(){}
function bad(message,code,statusCode){return{success:false,statusCode:statusCode||400,error:{code:code||'VALIDATION_ERROR',message}};}
function app(req){return appScope.fromRequest(req);}
function text(value){return String(value==null?'':value).trim();}
function json(value){return JSON.stringify(value&&typeof value==='object'&&!Array.isArray(value)?value:{});}
function parse(value){try{return JSON.parse(value||'{}');}catch(_){return{};}}
function stable(value){if(Array.isArray(value))return value.map(stable);if(value&&typeof value==='object')return Object.keys(value).sort().reduce((o,k)=>{o[k]=stable(value[k]);return o;},{});return value;}
function hash(value){return crypto.createHash('sha256').update(JSON.stringify(stable(value))).digest('hex');}
function markInputsChanged(ctx,setupId){ctx.db.query("UPDATE scheduler_setups SET input_revision=input_revision+1,updated_at=datetime('now') WHERE id=?",[setupId]);ctx.db.query("UPDATE scheduler_versions SET stale=1,updated_at=datetime('now') WHERE scheduler_setup_id=? AND status NOT IN ('published','superseded')",[setupId]);}
function year(ctx,id,appId){return ctx.db.query('SELECT * FROM academic_years WHERE id=? AND app_id=?',[id,appId]).rows[0];}
function setup(ctx,id,appId){return ctx.db.query('SELECT * FROM scheduler_setups WHERE id=? AND app_id=?',[id,appId]).rows[0];}
function hydrate(ctx,row){if(!row)return null;row.configuration=parse(row.configuration_json);delete row.configuration_json;row.scopes=ctx.db.query('SELECT * FROM scheduler_scopes WHERE scheduler_setup_id=? AND app_id=? ORDER BY name,id',[row.id,row.app_id]).rows.map(hydrateScope);return row;}
function hydrateScope(row){row.configuration=parse(row.configuration_json);delete row.configuration_json;return row;}
function emit(ctx,channel,record){ctx.events.publish(channel,{entityId:record.id,record,source:'scheduler',__module:'scheduler'});}

async function getSetup(req,ctx){const appId=app(req),yearId=text(req.query.academic_year_id);if(!yearId)return bad('academic_year_id is required');return{success:true,setup:hydrate(ctx,ctx.db.query('SELECT * FROM scheduler_setups WHERE app_id=? AND academic_year_id=?',[appId,yearId]).rows[0])};}

async function saveSetup(req,ctx){
  const b=req.body||{},appId=app(req),yearId=Number(b.academic_year_id);
  if(!yearId||!year(ctx,yearId,appId))return bad('Academic year not found','NOT_FOUND',404);
  if(!text(b.name))return bad('Setup name is required');
  if(!['school','selected'].includes(b.scope_mode))return bad('scope_mode must be school or selected');
  if(b.status!=null&&!['draft','active','withdrawn'].includes(b.status))return bad('Invalid setup status');
  const week=Number(b.week_starts_on==null?1:b.week_starts_on);
  if(!Number.isInteger(week)||week<1||week>7)return bad('week_starts_on must be between 1 and 7');
  const timezone=text(b.timezone)||'Asia/Riyadh';
  let row=ctx.db.query('SELECT * FROM scheduler_setups WHERE app_id=? AND academic_year_id=?',[appId,yearId]).rows[0];
  if(row){ctx.db.query("UPDATE scheduler_setups SET name=?,scope_mode=?,status=?,timezone=?,week_starts_on=?,configuration_json=?,version=version+1,updated_at=datetime('now') WHERE id=?",[text(b.name),b.scope_mode,b.status||row.status,timezone,week,json(b.configuration),row.id]);}
  else {const x=ctx.db.query('INSERT INTO scheduler_setups(app_id,academic_year_id,name,scope_mode,status,timezone,week_starts_on,configuration_json) VALUES(?,?,?,?,?,?,?,?)',[appId,yearId,text(b.name),b.scope_mode,b.status||'draft',timezone,week,json(b.configuration)]);row={id:x.lastInsertRowid};}
  if(b.scope_mode==='school'){
    const found=ctx.db.query("SELECT id FROM scheduler_scopes WHERE scheduler_setup_id=? AND app_id=? AND scope_type='school' AND scope_ref='school'",[row.id,appId]).rows[0];
    if(found)ctx.db.query("UPDATE scheduler_scopes SET status='active',updated_at=datetime('now') WHERE id=?",[found.id]);
    else ctx.db.query("INSERT INTO scheduler_scopes(app_id,scheduler_setup_id,external_key,scope_type,scope_ref,name,status) VALUES(?,?,?,'school','school','Whole school','active')",[appId,row.id,'school']);
  }
  const saved=hydrate(ctx,setup(ctx,row.id,appId));emit(ctx,'scheduler.setup.saved',saved);return{success:true,setup:saved};
}

function locateSetup(ctx,req){const appId=app(req),id=text(req.query.scheduler_setup_id||(req.body||{}).scheduler_setup_id);return{id,appId,row:id?setup(ctx,id,appId):null};}
async function listScopes(req,ctx){const target=locateSetup(ctx,req);if(!target.row)return bad('Scheduler setup not found','NOT_FOUND',404);let rows=ctx.db.query('SELECT * FROM scheduler_scopes WHERE scheduler_setup_id=? AND app_id=? ORDER BY name,id',[target.id,target.appId]).rows;if(req.query.status)rows=rows.filter(x=>x.status===req.query.status);return{success:true,scopes:rows.map(hydrateScope),total:rows.length};}
async function addScope(req,ctx){
  const b=req.body||{},target=locateSetup(ctx,req);if(!target.row)return bad('Scheduler setup not found','NOT_FOUND',404);
  const value={type:b.scope_type,id:text(b.scope_ref)};try{contract.validateScope(value);}catch(e){return bad(e.message);}
  if(target.row.scope_mode==='school'&&value.type!=='school')return bad('Change setup to selected scope mode before adding selected scopes');
  if(!text(b.external_key)||!text(b.name))return bad('external_key and name are required');
  try{const x=ctx.db.query('INSERT INTO scheduler_scopes(app_id,scheduler_setup_id,external_key,scope_type,scope_ref,name,configuration_json,status) VALUES(?,?,?,?,?,?,?,?)',[target.appId,target.id,text(b.external_key),value.type,value.id,text(b.name),json(b.configuration),b.status||'active']),row=hydrateScope(ctx.db.query('SELECT * FROM scheduler_scopes WHERE id=?',[x.lastInsertRowid]).rows[0]);emit(ctx,'scheduler.scope.created',row);return{success:true,scope:row};}catch(e){if(String(e.message).includes('UNIQUE'))return bad('Scope identity already exists','SCOPE_EXISTS',409);throw e;}
}
function findScope(ctx,req){return ctx.db.query('SELECT * FROM scheduler_scopes WHERE id=? AND app_id=?',[req.params.id,app(req)]).rows[0];}
async function updateScope(req,ctx){const row=findScope(ctx,req),b=req.body||{};if(!row)return bad('Scope not found','NOT_FOUND',404);const value={type:b.scope_type||row.scope_type,id:text(b.scope_ref||row.scope_ref)};try{contract.validateScope(value);}catch(e){return bad(e.message);}if(!text(b.name||row.name))return bad('Scope name is required');ctx.db.query("UPDATE scheduler_scopes SET external_key=?,scope_type=?,scope_ref=?,name=?,configuration_json=?,updated_at=datetime('now') WHERE id=?",[text(b.external_key||row.external_key),value.type,value.id,text(b.name||row.name),b.configuration===undefined?row.configuration_json:json(b.configuration),row.id]);const saved=hydrateScope(ctx.db.query('SELECT * FROM scheduler_scopes WHERE id=?',[row.id]).rows[0]);emit(ctx,'scheduler.scope.updated',saved);return{success:true,scope:saved};}
async function setScopeStatus(req,ctx,status,channel){const row=findScope(ctx,req);if(!row)return bad('Scope not found','NOT_FOUND',404);if(row.scope_type==='school'&&status==='withdrawn'){const parent=setup(ctx,row.scheduler_setup_id,row.app_id);if(parent&&parent.scope_mode==='school')return bad('The whole-school scope cannot be withdrawn while setup uses school mode');}ctx.db.query("UPDATE scheduler_scopes SET status=?,updated_at=datetime('now') WHERE id=?",[status,row.id]);const saved=hydrateScope(ctx.db.query('SELECT * FROM scheduler_scopes WHERE id=?',[row.id]).rows[0]);emit(ctx,channel,saved);return{success:true,scope:saved};}
async function withdrawScope(req,ctx){return setScopeStatus(req,ctx,'withdrawn','scheduler.scope.withdrawn');}
async function reinstateScope(req,ctx){return setScopeStatus(req,ctx,'active','scheduler.scope.reinstated');}

function structureSnapshot(ctx,target){
  const cycle=ctx.db.query('SELECT * FROM scheduler_cycles WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]).rows[0]||null;
  if(cycle){cycle.week_labels=parse(cycle.week_labels_json);delete cycle.week_labels_json;}
  const templates=ctx.db.query('SELECT * FROM scheduler_period_templates WHERE scheduler_setup_id=? AND app_id=? ORDER BY name,id',[target.id,target.appId]).rows;
  const days=ctx.db.query('SELECT * FROM scheduler_day_patterns WHERE scheduler_setup_id=? AND app_id=? ORDER BY scheduler_scope_id,cycle_week,day_index',[target.id,target.appId]).rows;
  days.forEach(day=>{day.is_operating_day=Boolean(day.is_operating_day);day.periods=ctx.db.query('SELECT * FROM scheduler_periods WHERE day_pattern_id=? AND app_id=? ORDER BY sequence,id',[day.id,target.appId]).rows.map(period=>{period.counts_as_instruction=Boolean(period.counts_as_instruction);period.configuration=parse(period.configuration_json);delete period.configuration_json;return period;});});
  return{cycle,period_templates:templates,day_patterns:days};
}
async function getStructures(req,ctx){const target=locateSetup(ctx,req);if(!target.row)return bad('Scheduler setup not found','NOT_FOUND',404);return{success:true,structures:structureSnapshot(ctx,target)};}
function validTime(value){return/^([01]\d|2[0-3]):[0-5]\d$/.test(value);}
function validateStructures(ctx,target,b){
  try{contract.validateCycle(b.cycle);}catch(e){return e.message;}
  if(!text(b.cycle.name))return'cycle.name is required';
  if(!Array.isArray(b.period_templates)||!b.period_templates.length)return'At least one period template is required';
  const keys=new Set();for(const item of b.period_templates){try{contract.validatePeriodTemplate(item);}catch(e){return e.message;}if(keys.has(item.external_key))return'Duplicate period template key';keys.add(item.external_key);}
  if(!Array.isArray(b.day_patterns)||!b.day_patterns.length)return'At least one day pattern is required';
  const dayKeys=new Set();for(const day of b.day_patterns){const scopeRow=ctx.db.query("SELECT id FROM scheduler_scopes WHERE id=? AND scheduler_setup_id=? AND app_id=? AND status='active'",[day.scheduler_scope_id,target.id,target.appId]).rows[0];if(!scopeRow)return'Day pattern scope is not active in this setup';if(!Number.isInteger(+day.cycle_week)||+day.cycle_week<1||+day.cycle_week>+b.cycle.week_count)return'cycle_week is outside the configured rotation';if(!Number.isInteger(+day.day_index)||+day.day_index<1||+day.day_index>7)return'day_index must be between 1 and 7';const dk=day.scheduler_scope_id+':'+day.cycle_week+':'+day.day_index;if(dayKeys.has(dk))return'Duplicate day pattern';dayKeys.add(dk);if(!text(day.name))return'Day pattern name is required';const periods=day.periods||[];if(day.is_operating_day!==false&&!periods.length)return'Operating days require at least one period';let previousEnd=null,sequences=new Set(),periodKeys=new Set();for(const p of periods){if(!text(p.external_key)||!text(p.name))return'Period external_key and name are required';if(!Number.isInteger(+p.sequence)||+p.sequence<1||sequences.has(+p.sequence))return'Period sequences must be unique positive integers';sequences.add(+p.sequence);if(periodKeys.has(p.external_key))return'Period keys must be unique within a day';periodKeys.add(p.external_key);if(!validTime(p.starts_at)||!validTime(p.ends_at)||p.starts_at>=p.ends_at)return'Periods require valid increasing HH:MM times';if(previousEnd&&p.starts_at<previousEnd)return'Periods cannot overlap';previousEnd=p.ends_at;if(!['instruction','break','lunch','assembly','meeting','transition','other'].includes(p.kind))return'Invalid period kind';if(p.period_template_key&&!keys.has(p.period_template_key))return'Period template key was not declared';}}
  return null;
}
async function saveStructures(req,ctx){
  const b=req.body||{},target=locateSetup(ctx,req);if(!target.row)return bad('Scheduler setup not found','NOT_FOUND',404);const problem=validateStructures(ctx,target,b);if(problem)return bad(problem);
  ctx.db.transaction(db=>{
    db.query('DELETE FROM scheduler_periods WHERE day_pattern_id IN (SELECT id FROM scheduler_day_patterns WHERE scheduler_setup_id=? AND app_id=?)',[target.id,target.appId]);db.query('DELETE FROM scheduler_day_patterns WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]);db.query('DELETE FROM scheduler_period_templates WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]);db.query('DELETE FROM scheduler_cycles WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]);
    db.query('INSERT INTO scheduler_cycles(app_id,scheduler_setup_id,name,week_count,week_labels_json,status) VALUES(?,?,?,?,?,?)',[target.appId,target.id,text(b.cycle.name),+b.cycle.week_count,JSON.stringify(b.cycle.week_labels),b.cycle.status||'active']);
    const templateIds={};b.period_templates.forEach(t=>{const x=db.query('INSERT INTO scheduler_period_templates(app_id,scheduler_setup_id,external_key,name,duration_minutes,multiplier,status) VALUES(?,?,?,?,?,?,?)',[target.appId,target.id,text(t.external_key),text(t.name),+t.duration_minutes,t.multiplier==null?1:+t.multiplier,t.status||'active']);templateIds[t.external_key]=x.lastInsertRowid;});
    b.day_patterns.forEach(day=>{const x=db.query('INSERT INTO scheduler_day_patterns(app_id,scheduler_setup_id,scheduler_scope_id,cycle_week,day_index,name,is_operating_day,status) VALUES(?,?,?,?,?,?,?,?)',[target.appId,target.id,+day.scheduler_scope_id,+day.cycle_week,+day.day_index,text(day.name),day.is_operating_day===false?0:1,day.status||'active']);(day.periods||[]).forEach(p=>db.query('INSERT INTO scheduler_periods(app_id,day_pattern_id,period_template_id,external_key,name,sequence,starts_at,ends_at,kind,counts_as_instruction,configuration_json) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[target.appId,x.lastInsertRowid,p.period_template_key?templateIds[p.period_template_key]:null,text(p.external_key),text(p.name),+p.sequence,p.starts_at,p.ends_at,p.kind,p.counts_as_instruction===false?0:1,json(p.configuration)]));});
    db.query("UPDATE scheduler_setups SET version=version+1,updated_at=datetime('now') WHERE id=?",[target.id]);
  });
  markInputsChanged(ctx,target.id);
  const structures=structureSnapshot(ctx,target);emit(ctx,'scheduler.structures.saved',{id:target.id,scheduler_setup_id:target.id,structures});return{success:true,structures};
}

function rulesSnapshot(ctx,target){
  const availability=ctx.db.query('SELECT * FROM scheduler_availability WHERE scheduler_setup_id=? AND app_id=? ORDER BY entity_type,entity_ref,id',[target.id,target.appId]).rows.map(row=>{row.condition=parse(row.condition_json);delete row.condition_json;return row;});
  const constraints=ctx.db.query('SELECT * FROM scheduler_constraints WHERE scheduler_setup_id=? AND app_id=? ORDER BY level,code,id',[target.id,target.appId]).rows.map(row=>{row.parameters=parse(row.parameters_json);delete row.parameters_json;return row;});
  const travel_times=ctx.db.query('SELECT * FROM scheduler_travel_times WHERE scheduler_setup_id=? AND app_id=? ORDER BY from_location_ref,to_location_ref,id',[target.id,target.appId]).rows.map(row=>{row.bidirectional=Boolean(row.bidirectional);return row;});
  return{availability,constraints,travel_times};
}
async function getRules(req,ctx){const target=locateSetup(ctx,req);if(!target.row)return bad('Scheduler setup not found','NOT_FOUND',404);return{success:true,rules:rulesSnapshot(ctx,target)};}
function validateRules(ctx,target,b){
  if(!Array.isArray(b.availability)||!Array.isArray(b.constraints)||!Array.isArray(b.travel_times))return'availability, constraints and travel_times must be arrays';
  const cycle=ctx.db.query('SELECT week_count FROM scheduler_cycles WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]).rows[0];if(!cycle)return'Timetable structures must be configured before rules';
  const availabilityKeys=new Set();for(const item of b.availability){if(!text(item.external_key)||availabilityKeys.has(item.external_key))return'Availability external keys must be present and unique';availabilityKeys.add(item.external_key);try{contract.validateAvailability({external_key:text(item.external_key),entity_type:text(item.entity_type),entity_id:text(item.entity_ref),state:item.state,week_index:item.cycle_week});}catch(e){return e.message;}if(!['staff','room','resource','scope','teaching_group','location'].includes(item.entity_type))return'Unsupported availability entity type';if(item.cycle_week!=null&&+item.cycle_week>+cycle.week_count)return'Availability cycle_week is outside the configured rotation';if(item.day_index!=null&&(!Number.isInteger(+item.day_index)||+item.day_index<1||+item.day_index>7))return'Availability day_index must be between 1 and 7';if((item.starts_at&&!validTime(item.starts_at))||(item.ends_at&&!validTime(item.ends_at))||(item.starts_at&&item.ends_at&&item.starts_at>=item.ends_at))return'Availability times must be valid increasing HH:MM values';if((item.starts_at&&!item.ends_at)||(!item.starts_at&&item.ends_at))return'Availability start and end times must be supplied together';if(item.valid_from&&item.valid_to&&item.valid_from>item.valid_to)return'Availability valid_from must not follow valid_to';if(!text(item.reason))return'Every availability rule requires a reason';}
  const constraintCodes=new Set();for(const item of b.constraints){if(constraintCodes.has(item.code))return'Constraint codes must be unique';constraintCodes.add(item.code);try{contract.validateConstraint({code:text(item.code),name:text(item.name),level:item.level,scope:{type:item.scope_type,id:text(item.scope_ref)},weight:item.weight==null?1:item.weight,explanation_template:text(item.explanation_template)});}catch(e){return e.message;}if(!text(item.rule_type))return'Constraint rule_type is required';}
  const pairs=new Set();for(const item of b.travel_times){if(!text(item.from_location_ref)||!text(item.to_location_ref)||item.from_location_ref===item.to_location_ref)return'Travel times require two different locations';if(!Number.isInteger(+item.minutes)||+item.minutes<0)return'Travel minutes must be a non-negative integer';if(!text(item.reason))return'Every travel time requires a reason';const direct=item.from_location_ref+'>'+item.to_location_ref,reverse=item.to_location_ref+'>'+item.from_location_ref;if(pairs.has(direct)||(item.bidirectional!==false&&pairs.has(reverse)))return'Duplicate travel-time relationship';pairs.add(direct);}
  return null;
}
async function saveRules(req,ctx){
  const b=req.body||{},target=locateSetup(ctx,req);if(!target.row)return bad('Scheduler setup not found','NOT_FOUND',404);const problem=validateRules(ctx,target,b);if(problem)return bad(problem);
  ctx.db.transaction(db=>{
    db.query('DELETE FROM scheduler_availability WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]);db.query('DELETE FROM scheduler_constraints WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]);db.query('DELETE FROM scheduler_travel_times WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]);
    b.availability.forEach(item=>db.query('INSERT INTO scheduler_availability(app_id,scheduler_setup_id,external_key,entity_type,entity_ref,state,cycle_week,day_index,starts_at,ends_at,valid_from,valid_to,condition_json,reason,source,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[target.appId,target.id,text(item.external_key),item.entity_type,text(item.entity_ref),item.state,item.cycle_week==null?null:+item.cycle_week,item.day_index==null?null:+item.day_index,item.starts_at||null,item.ends_at||null,item.valid_from||null,item.valid_to||null,json(item.condition),text(item.reason),text(item.source)||'manual',item.status||'active']));
    b.constraints.forEach(item=>db.query('INSERT INTO scheduler_constraints(app_id,scheduler_setup_id,code,name,level,scope_type,scope_ref,rule_type,weight,parameters_json,explanation_template,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[target.appId,target.id,text(item.code),text(item.name),item.level,item.scope_type,text(item.scope_ref),text(item.rule_type),item.weight==null?1:+item.weight,json(item.parameters),text(item.explanation_template),item.status||'active']));
    b.travel_times.forEach(item=>db.query('INSERT INTO scheduler_travel_times(app_id,scheduler_setup_id,from_location_ref,to_location_ref,minutes,bidirectional,reason,status) VALUES(?,?,?,?,?,?,?,?)',[target.appId,target.id,text(item.from_location_ref),text(item.to_location_ref),+item.minutes,item.bidirectional===false?0:1,text(item.reason),item.status||'active']));
    db.query("UPDATE scheduler_setups SET version=version+1,updated_at=datetime('now') WHERE id=?",[target.id]);
  });
  markInputsChanged(ctx,target.id);
  const rules=rulesSnapshot(ctx,target);emit(ctx,'scheduler.rules.saved',{id:target.id,scheduler_setup_id:target.id,rules});return{success:true,rules};
}

function hydrateRequirement(row){for(const field of ['eligible_staff_ids','eligible_room_ids','eligible_resource_ids','allowed_period_template_keys']){row[field]=parse(row[field+'_json']);delete row[field+'_json'];}row.attributes=parse(row.attributes_json);delete row.attributes_json;return row;}
async function getRequirements(req,ctx){const target=locateSetup(ctx,req);if(!target.row)return bad('Scheduler setup not found','NOT_FOUND',404);let rows=ctx.db.query('SELECT * FROM scheduler_requirements WHERE scheduler_setup_id=? AND app_id=? ORDER BY name,id',[target.id,target.appId]).rows;if(req.query.status)rows=rows.filter(x=>x.status===req.query.status);return{success:true,requirements:rows.map(hydrateRequirement),total:rows.length};}
async function saveRequirements(req,ctx){
  const b=req.body||{},target=locateSetup(ctx,req);if(!target.row)return bad('Scheduler setup not found','NOT_FOUND',404);if(!Array.isArray(b.requirements))return bad('requirements must be an array');const seen=new Set();for(const item of b.requirements){try{contract.validateRequirement(item);}catch(e){return bad(e.message);}if(seen.has(item.external_key))return bad('Requirement external keys must be unique');seen.add(item.external_key);if(String(item.academic_year_id)!==String(target.row.academic_year_id))return bad('Requirement academic year does not match setup');}
  ctx.db.transaction(db=>{db.query('DELETE FROM scheduler_requirements WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]);b.requirements.forEach(item=>db.query('INSERT INTO scheduler_requirements(app_id,scheduler_setup_id,external_key,academic_year_id,teaching_group_external_key,name,occurrences_per_cycle,duration_minutes,eligible_staff_ids_json,eligible_room_ids_json,eligible_resource_ids_json,allowed_period_template_keys_json,attributes_json,valid_from,valid_to,source,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[target.appId,target.id,text(item.external_key),String(item.academic_year_id),text(item.teaching_group_external_key),text(item.name),+item.occurrences_per_cycle,+item.duration_minutes,JSON.stringify(item.eligible_staff_ids||[]),JSON.stringify(item.eligible_room_ids||[]),JSON.stringify(item.eligible_resource_ids||[]),JSON.stringify(item.allowed_period_template_keys||[]),json(item.attributes),item.valid_from||null,item.valid_to||null,text(item.source)||'manual',item.status||'draft']));db.query("UPDATE scheduler_setups SET version=version+1,updated_at=datetime('now') WHERE id=?",[target.id]);});
  markInputsChanged(ctx,target.id);const rows=ctx.db.query('SELECT * FROM scheduler_requirements WHERE scheduler_setup_id=? AND app_id=? ORDER BY name,id',[target.id,target.appId]).rows.map(hydrateRequirement);emit(ctx,'scheduling_requirement.updated',{id:target.id,scheduler_setup_id:target.id,requirements:rows});return{success:true,requirements:rows};
}
function minutes(value){const p=value.split(':').map(Number);return p[0]*60+p[1];}
function overlaps(a,b){return a.week_index===b.week_index&&a.day_index===b.day_index&&a.start_time<b.end_time&&b.start_time<a.end_time;}
function applies(rule,candidate,entityType,entityRef){if(rule.entity_type!==entityType||rule.entity_ref!==entityRef||rule.status!=='active')return false;if(rule.cycle_week!=null&&+rule.cycle_week!==+candidate.week_index)return false;if(rule.day_index!=null&&+rule.day_index!==+candidate.day_index)return false;if(rule.starts_at&&!(candidate.start_time<rule.ends_at&&rule.starts_at<candidate.end_time))return false;return true;}
function addFinding(findings,candidate,code,level,message,evidence,penalty){findings.push({candidate_external_key:candidate&&candidate.external_key||null,constraint_code:code,level,message,evidence:evidence||{},penalty:+(penalty||0)});}
function validateCandidateSet(ctx,target,candidates){
  const requirements=new Map(ctx.db.query("SELECT * FROM scheduler_requirements WHERE scheduler_setup_id=? AND app_id=? AND status='active'",[target.id,target.appId]).rows.map(row=>{row=hydrateRequirement(row);return[row.external_key,row];}));
  const availability=rulesSnapshot(ctx,target).availability,constraints=rulesSnapshot(ctx,target).constraints.filter(x=>x.status==='active'),travel=rulesSnapshot(ctx,target).travel_times.filter(x=>x.status==='active');const findings=[],valid=[];
  const cycle=ctx.db.query('SELECT week_count FROM scheduler_cycles WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]).rows[0];
  for(const c of candidates){try{contract.validatePlacement({external_key:text(c.external_key),schedule_version_id:'candidate',requirement_external_key:text(c.requirement_external_key),teaching_group_external_key:text(c.teaching_group_external_key),week_index:c.week_index,day_index:c.day_index,start_time:c.start_time,end_time:c.end_time,status:'proposed'});}catch(e){addFinding(findings,c,'CANDIDATE_INVALID','hard',e.message,{candidate:c});continue;}const req=requirements.get(c.requirement_external_key);if(!req){addFinding(findings,c,'REQUIREMENT_NOT_ACTIVE','hard','Candidate does not reference an active scheduling requirement.',{requirement_external_key:c.requirement_external_key});continue;}if(c.teaching_group_external_key!==req.teaching_group_external_key)addFinding(findings,c,'TEACHING_GROUP_MISMATCH','hard','Candidate teaching group does not match its requirement.',{});if(+c.week_index>+(cycle&&cycle.week_count||0))addFinding(findings,c,'WEEK_OUTSIDE_CYCLE','hard','Candidate week is outside the configured rotation.',{week_index:c.week_index});if(!validTime(c.start_time)||!validTime(c.end_time)||c.start_time>=c.end_time)addFinding(findings,c,'TIME_INVALID','hard','Candidate requires valid increasing HH:MM times.',{});if(validTime(c.start_time)&&validTime(c.end_time)&&minutes(c.end_time)-minutes(c.start_time)!==+req.duration_minutes)addFinding(findings,c,'DURATION_MISMATCH','hard','Candidate duration does not match the scheduling requirement.',{required_minutes:req.duration_minutes,actual_minutes:minutes(c.end_time)-minutes(c.start_time)});
    const day=ctx.db.query("SELECT * FROM scheduler_day_patterns WHERE scheduler_setup_id=? AND scheduler_scope_id=? AND cycle_week=? AND day_index=? AND status='active'",[target.id,c.scheduler_scope_id,c.week_index,c.day_index]).rows[0];if(!day||!day.is_operating_day)addFinding(findings,c,'DAY_UNAVAILABLE','hard','Candidate is not on an active operating day for its scope.',{});else{const periods=ctx.db.query('SELECT p.*,t.external_key template_key FROM scheduler_periods p LEFT JOIN scheduler_period_templates t ON t.id=p.period_template_id WHERE p.day_pattern_id=? ORDER BY p.sequence',[day.id]).rows,covered=periods.filter(p=>p.kind==='instruction'&&p.starts_at<c.end_time&&c.start_time<p.ends_at);if(!covered.length||c.start_time<covered[0].starts_at||c.end_time>covered[covered.length-1].ends_at)addFinding(findings,c,'OUTSIDE_INSTRUCTION','hard','Candidate is not contained within instructional timetable periods.',{});if(req.allowed_period_template_keys.length&&covered.some(p=>!req.allowed_period_template_keys.includes(p.template_key)))addFinding(findings,c,'PERIOD_TEMPLATE_NOT_ALLOWED','hard','Candidate uses a period template not allowed by its requirement.',{allowed:req.allowed_period_template_keys});c._period_keys=covered.map(p=>p.external_key);c._next_kind=periods.find(p=>p.starts_at>=c.end_time)&&periods.find(p=>p.starts_at>=c.end_time).kind;}
    for(const spec of [['staff',c.staff_ids||[],req.eligible_staff_ids],['room',c.room_ids||[],req.eligible_room_ids],['resource',c.resource_ids||[],req.eligible_resource_ids]]){for(const ref of spec[1]){if(spec[2].length&&!spec[2].includes(ref))addFinding(findings,c,'ENTITY_NOT_ELIGIBLE','hard','Assigned '+spec[0]+' is not eligible for this requirement.',{entity_type:spec[0],entity_ref:ref});for(const rule of availability.filter(x=>applies(x,c,spec[0],ref))){if(rule.state==='unavailable')addFinding(findings,c,'ENTITY_UNAVAILABLE','hard',rule.reason,{entity_type:spec[0],entity_ref:ref,availability_key:rule.external_key});else if(rule.state==='discouraged')addFinding(findings,c,'ENTITY_DISCOURAGED','soft',rule.reason,{entity_type:spec[0],entity_ref:ref},1);else if(rule.state==='conditional')addFinding(findings,c,'ENTITY_CONDITIONAL','advisory',rule.reason,{entity_type:spec[0],entity_ref:ref,condition:rule.condition});}}}valid.push(c);
  }
  for(let i=0;i<valid.length;i++)for(let j=i+1;j<valid.length;j++)if(overlaps(valid[i],valid[j]))for(const field of ['staff_ids','room_ids','resource_ids']){const shared=(valid[i][field]||[]).filter(x=>(valid[j][field]||[]).includes(x));if(shared.length)addFinding(findings,valid[j],'DOUBLE_BOOKING','hard','Candidate double-books '+field.replace('_ids','')+'.',{shared,conflicts_with:valid[i].external_key});}
  const counts={};valid.forEach(c=>{counts[c.requirement_external_key]=(counts[c.requirement_external_key]||0)+1;});let unplaced=0;requirements.forEach(req=>{const missing=Math.max(0,+req.occurrences_per_cycle-(counts[req.external_key]||0));unplaced+=missing;if(missing)addFinding(findings,null,'REQUIREMENT_UNPLACED','hard',missing+' occurrence(s) remain unplaced for '+req.name+'.',{requirement_external_key:req.external_key,missing});});
  for(const c of valid)for(const rule of constraints){const attrs=requirements.get(c.requirement_external_key).attributes||{},cats=(rule.parameters.subject_categories||[]);if(cats.length&&!cats.includes(attrs.subject_category))continue;if(rule.rule_type==='excluded_period'&&(rule.parameters.period_keys||[]).some(x=>(c._period_keys||[]).includes(x)))addFinding(findings,c,rule.code,rule.level,rule.explanation_template,{period_keys:c._period_keys},rule.weight);if(rule.rule_type==='time_window_preference'&&rule.parameters.before&&c.end_time>rule.parameters.before)addFinding(findings,c,rule.code,rule.level,rule.explanation_template,{boundary:rule.parameters.before},rule.weight);if(rule.rule_type==='adjacency_preference'&&(rule.parameters.next_kinds||[]).length&&!(rule.parameters.next_kinds||[]).includes(c._next_kind))addFinding(findings,c,rule.code,rule.level,rule.explanation_template,{next_kind:c._next_kind||null},rule.weight);}
  const byStaff={};valid.forEach(c=>(c.staff_ids||[]).forEach(s=>{(byStaff[s]||(byStaff[s]=[])).push(c);}));Object.keys(byStaff).forEach(staff=>{const rows=byStaff[staff].sort((a,b)=>a.week_index-b.week_index||a.day_index-b.day_index||a.start_time.localeCompare(b.start_time));for(let i=1;i<rows.length;i++){const a=rows[i-1],b=rows[i];if(a.week_index!==b.week_index||a.day_index!==b.day_index||!a.location_ref||!b.location_ref||a.location_ref===b.location_ref)continue;const rule=travel.find(x=>(x.from_location_ref===a.location_ref&&x.to_location_ref===b.location_ref)||(x.bidirectional&&x.from_location_ref===b.location_ref&&x.to_location_ref===a.location_ref));if(rule&&minutes(b.start_time)-minutes(a.end_time)<rule.minutes)addFinding(findings,b,'TRAVEL_TIME_INSUFFICIENT','hard','Insufficient travel time between consecutive locations.',{staff_id:staff,from:a.location_ref,to:b.location_ref,required_minutes:rule.minutes});}});
  const hard=findings.filter(x=>x.level==='hard').length,soft=findings.filter(x=>x.level==='soft').reduce((n,x)=>n+x.penalty,0),advisory=findings.filter(x=>x.level==='advisory').length;return{findings,outcome:contract.rankOutcome({hard_violations:hard,soft_penalty:soft,advisory_count:advisory,unplaced_requirements:unplaced})};
}
async function validateCandidates(req,ctx){const b=req.body||{},target=locateSetup(ctx,req);if(!target.row)return bad('Scheduler setup not found','NOT_FOUND',404);if(!text(b.external_key)||!Array.isArray(b.candidates))return bad('external_key and candidates are required');const report=validateCandidateSet(ctx,target,b.candidates);try{const x=ctx.db.query('INSERT INTO scheduler_validation_runs(app_id,scheduler_setup_id,external_key,candidate_count,feasible,score,hard_violations,soft_penalty,advisory_count,unplaced_requirements) VALUES(?,?,?,?,?,?,?,?,?,?)',[target.appId,target.id,text(b.external_key),b.candidates.length,report.outcome.feasible?1:0,report.outcome.score,report.outcome.breakdown.hard_violations,report.outcome.breakdown.soft_penalty,report.outcome.breakdown.advisory_count,report.outcome.breakdown.unplaced_requirements]);report.findings.forEach(f=>ctx.db.query('INSERT INTO scheduler_validation_findings(validation_run_id,candidate_external_key,constraint_code,level,message,evidence_json,penalty) VALUES(?,?,?,?,?,?,?)',[x.lastInsertRowid,f.candidate_external_key,f.constraint_code,f.level,f.message,json(f.evidence),f.penalty]));const run=await validationRun(ctx,x.lastInsertRowid,target.appId);emit(ctx,'schedule.validated',{id:x.lastInsertRowid,scheduler_setup_id:target.id,report:run});return{success:true,validation_run:run};}catch(e){if(String(e.message).includes('UNIQUE'))return bad('Validation run external key already exists','VALIDATION_RUN_EXISTS',409);throw e;}}
async function validationRun(ctx,id,appId){const row=ctx.db.query('SELECT * FROM scheduler_validation_runs WHERE id=? AND app_id=?',[id,appId]).rows[0];if(!row)return null;row.feasible=Boolean(row.feasible);row.findings=ctx.db.query('SELECT * FROM scheduler_validation_findings WHERE validation_run_id=? ORDER BY id',[id]).rows.map(f=>{f.evidence=parse(f.evidence_json);delete f.evidence_json;return f;});return row;}

