async function getValidationRun(req,ctx){const row=await validationRun(ctx,req.params.id,app(req));return row?{success:true,validation_run:row}:bad('Validation run not found','NOT_FOUND',404);}

function hydratePlacement(row){for(const f of ['staff_ids','room_ids','resource_ids']){row[f]=parse(row[f+'_json']);delete row[f+'_json'];}row.locked=Boolean(row.locked);return row;}
function hydrateVersion(ctx,row){row.feasible=Boolean(row.feasible);row.placements=ctx.db.query('SELECT * FROM scheduler_placements WHERE schedule_version_id=? AND app_id=? ORDER BY week_index,day_index,start_time,id',[row.id,row.app_id]).rows.map(hydratePlacement);return row;}
async function listVersions(req,ctx){const target=locateSetup(ctx,req);if(!target.row)return bad('Scheduler setup not found','NOT_FOUND',404);const pageNumber=Math.max(1,+req.query.page||1),limit=Math.min(50,Math.max(1,+req.query.limit||50)),total=+ctx.db.query('SELECT COUNT(*) total FROM scheduler_versions WHERE scheduler_setup_id=? AND app_id=?',[target.id,target.appId]).rows[0].total,rows=ctx.db.query('SELECT * FROM scheduler_versions WHERE scheduler_setup_id=? AND app_id=? ORDER BY score,alternative_number,id LIMIT ? OFFSET ?',[target.id,target.appId,limit,(pageNumber-1)*limit]).rows.map(x=>hydrateVersion(ctx,x));return{success:true,versions:rows,total,page:pageNumber,limit};}
